//! SI.05, claims R3 and R4 over `class_hierarchy.ecore`, for the many-valued
//! reference none of the five checked-in crates has: `Class.supertypes`
//! (`[0, *]`), beside `StructuralFeature.typ` (`[1, 1]`) and
//! `Reference.opposite` (`[0, 1]`). No reference of this metamodel declares
//! an `eOpposite`, so none is left out.
//!
//! The generated runtime is `examples/class_hierarchy.ecore` generated by
//! Arachne d81cae8 (`arachne generate -p class_hierarchy_crdt`), its three
//! source files copied unchanged into `fixtures/si05/class_hierarchy/` and
//! compiled here as this test's own modules (`crate::classifiers`,
//! `crate::references`, `crate::package`, which is how the files name each
//! other). Their sha256 are in the spec, section 5.3. The interpreted path
//! runs `fixtures/si05/class_hierarchy.identity.metamodel.json`, that
//! generation's `metamodel.json` with its three references moved to the new
//! rule. The harness is `si05_twin/mod.rs`.
//!
//! ```bash
//! cd generated/simpleuml_crdt && nice -n 10 cargo test -j 2 --test si05_reference_twin_class_hierarchy -- --nocapture
//! ```
#![allow(unexpected_cfgs, dead_code, unused_imports, clippy::all)]

// The generator's bytes, kept as written: rustfmt does not touch them.
#[rustfmt::skip]
#[path = "fixtures/si05/class_hierarchy/classifiers.rs"]
pub mod classifiers;
#[rustfmt::skip]
#[path = "fixtures/si05/class_hierarchy/package.rs"]
pub mod package;
#[rustfmt::skip]
#[path = "fixtures/si05/class_hierarchy/references.rs"]
pub mod references;

mod si05_twin;

use std::collections::BTreeSet;

use moirai_crdt::utils::membership::twins_log;
use moirai_protocol::broadcast::message::EventMessage;
use moirai_protocol::broadcast::tcsb::Tcsb;
use moirai_protocol::crdt::query::Read;
use moirai_protocol::replica::{IsReplica, Replica};
use serde_json::{Value, json};

use package::{ClassHierarchy, ClassHierarchyLog, ClassHierarchyValue};
use si05_twin::*;

type GenReplica = Replica<ClassHierarchyLog, Tcsb<ClassHierarchy>>;

struct Hierarchy {
    a: GenReplica,
    b: GenReplica,
}

impl GenSide for Hierarchy {
    type Msg = EventMessage<ClassHierarchy>;
    const ROOT_CLASS: &'static str = "Package";

    fn fresh() -> Self {
        let (a, b) = twins_log::<ClassHierarchyLog>();
        Hierarchy { a, b }
    }

    /// The root is a `record!`, so its `New` writes nothing a projection
    /// reads: the opener `ip13` uses for `bt.ecore`.
    fn opener() -> Value {
        json!({"Package": "New"})
    }

    fn mint_root() -> Value {
        json!({"Package": "New"})
    }

    fn on_root(_meta: &Meta, op: Value) -> Value {
        json!({ "Package": op })
    }

    fn arc(source: &str, feature: &str, target: &str) -> Option<&'static str> {
        match (source, feature, target) {
            ("Class", "supertypes", "Class") => Some("ClassToClass"),
            ("Attribute", "typ", "Class") => Some("AttributeToClass"),
            ("Attribute", "typ", "DataType") => Some("AttributeToDataType"),
            ("Reference", "typ", "Class") => Some("ReferenceToClass"),
            ("Reference", "typ", "DataType") => Some("ReferenceToDataType"),
            ("Reference", "opposite", "Reference") => Some("ReferenceToReference"),
            _ => None,
        }
    }

    fn feature_of(arc: &str) -> Option<&'static str> {
        match arc {
            "ClassToClass" => Some("supertypes"),
            "AttributeToClass"
            | "AttributeToDataType"
            | "ReferenceToClass"
            | "ReferenceToDataType" => Some("typ"),
            "ReferenceToReference" => Some("opposite"),
            _ => None,
        }
    }

    fn send(&mut self, writer: char, op: Value) -> Result<Self::Msg, String> {
        let op: ClassHierarchy = serde_json::from_value(op.clone()).unwrap_or_else(|error| {
            panic!("the typed encoder built no `ClassHierarchy`: {error}\n{op}")
        });
        let replica = if writer == 'a' {
            &mut self.a
        } else {
            &mut self.b
        };
        replica.send(op).map_err(|rejection| rejection.to_string())
    }

    fn receive(&mut self, at: char, message: Self::Msg) {
        if at == 'a' { &mut self.a } else { &mut self.b }.receive(message);
    }

    fn tag(message: &Self::Msg) -> String {
        let event = message.event();
        format!(
            "{}@{} L{}",
            event.id().origin_id(),
            event.id().seq(),
            event.lamport().val()
        )
    }

    fn graph(&self, at: char) -> (Vec<Value>, Vec<(usize, usize, Value)>) {
        let replica = if at == 'a' { &self.a } else { &self.b };
        let value: ClassHierarchyValue = replica.query(&Read::<ClassHierarchyValue>::new());
        let graph = &value.refs;
        let vertices = graph
            .node_indices()
            .map(|i| serde_json::to_value(&graph[i]).expect("a vertex serializes"))
            .collect();
        let arcs = graph
            .edge_indices()
            .map(|e| {
                let (from, to) = graph.edge_endpoints(e).expect("an edge has endpoints");
                (
                    from.index(),
                    to.index(),
                    serde_json::to_value(&graph[e]).expect("an edge serializes"),
                )
            })
            .collect();
        (vertices, arcs)
    }
}

fn read(relative: &str) -> Value {
    let path = format!("{}/{relative}", env!("CARGO_MANIFEST_DIR"));
    serde_json::from_str(
        &std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("reading {path}: {e}")),
    )
    .unwrap_or_else(|e| panic!("{path} is not JSON: {e}"))
}

fn today() -> Value {
    read("tests/fixtures/si05/class_hierarchy.today.metamodel.json")
}

fn identity() -> Value {
    read("tests/fixtures/si05/class_hierarchy.identity.metamodel.json")
}

const A: Label = 1;
const B: Label = 2;
const C: Label = 3;
const D: Label = 4;
const N: Label = 5;
const AT: Label = 6;
const R7: Label = 7;
const R8: Label = 8;
const R9: Label = 9;

/// `Package{content: [A{features: [AT, R7]}, B{features: [R8]}, C{features: [R9]}, D, N: DataType]}`,
/// written by `a` and delivered; `A` and `B` named.
fn opening() -> Vec<Step> {
    vec![
        edit('a', Action::Root),
        create('a', 0, "content", 0, "Class", A),
        create('a', 0, "content", 1, "Class", B),
        create('a', 0, "content", 2, "Class", C),
        create('a', 0, "content", 3, "Class", D),
        create('a', 0, "content", 4, "DataType", N),
        create('a', A, "features", 0, "Attribute", AT),
        create('a', A, "features", 1, "Reference", R7),
        create('a', B, "features", 0, "Reference", R8),
        create('a', C, "features", 0, "Reference", R9),
        rename('a', A, 'a'),
        rename('a', B, 'b'),
        Step::Deliver,
    ]
}

fn schedules() -> Vec<(&'static str, Vec<Step>)> {
    vec![
        (
            "many-valued links on both replicas, then every target renamed",
            vec![
                link('a', A, "supertypes", B),
                link('a', A, "supertypes", C),
                link('b', B, "supertypes", C),
                link('a', AT, "typ", N),
                link('a', R7, "typ", B),
                link('b', R7, "opposite", R8),
                Step::Deliver,
                rename('b', B, 'x'),
                rename('b', C, 'y'),
                rename('a', N, 'z'),
                Step::Deliver,
            ],
        ),
        (
            "concurrent adds to one many-valued reference",
            vec![
                link('a', A, "supertypes", B),
                link('b', A, "supertypes", D),
                Step::Deliver,
            ],
        ),
        (
            "an unlink concurrent with an unlink and relink of the same target",
            vec![
                link('a', A, "supertypes", B),
                Step::Deliver,
                unlink('a', A, "supertypes", B),
                unlink('b', A, "supertypes", B),
                link('b', A, "supertypes", B),
                Step::Deliver,
            ],
        ),
        (
            "a deletion concurrent with a link to the deleted class",
            vec![delete('a', D), link('b', A, "supertypes", D), Step::Deliver],
        ),
        (
            "Q2 on a many-valued reference",
            vec![
                delete('a', D),
                rename('b', D, 'r'),
                link('b', A, "supertypes", D),
                Step::Deliver,
            ],
        ),
        (
            "Q1 on a many-valued reference",
            vec![
                link('a', A, "supertypes", B),
                link('a', A, "supertypes", C),
                Step::Deliver,
                delete('a', C),
                rename('b', C, 'r'),
                Step::Deliver,
            ],
        ),
        (
            "a [1, 1] target deleted",
            vec![
                link('a', AT, "typ", B),
                link('a', R7, "typ", N),
                Step::Deliver,
                delete('b', B),
                Step::Deliver,
            ],
        ),
        (
            "concurrent retarget of a [0, 1] reference",
            vec![
                link('a', R7, "opposite", R8),
                Step::Deliver,
                unlink('a', R7, "opposite", R8),
                link('a', R7, "opposite", R7),
                unlink('b', R7, "opposite", R8),
                link('b', R7, "opposite", R9),
                Step::Deliver,
            ],
        ),
        (
            "concurrent retarget of a [0, 1] reference, then R9's class deleted",
            vec![
                link('a', R7, "opposite", R8),
                Step::Deliver,
                unlink('a', R7, "opposite", R8),
                link('a', R7, "opposite", R7),
                unlink('b', R7, "opposite", R8),
                link('b', R7, "opposite", R9),
                Step::Deliver,
                delete('a', C),
                Step::Deliver,
            ],
        ),
        (
            "a class its own supertype, then deleted",
            vec![
                link('a', A, "supertypes", A),
                link('a', B, "supertypes", A),
                Step::Deliver,
                delete('b', A),
                Step::Deliver,
            ],
        ),
        (
            "a full typ refuses a second link and its unlink",
            vec![
                link('a', AT, "typ", B),
                Step::Deliver,
                link('a', AT, "typ", C),
                unlink('b', AT, "typ", B),
                Step::Deliver,
            ],
        ),
    ]
}

fn expected(rows: &[(Label, &str, &[Label])]) -> Projection {
    rows.iter()
        .filter(|(_, _, targets)| !targets.is_empty())
        .map(|(source, feature, targets)| {
            (
                (*source, feature.to_string()),
                targets.iter().copied().collect(),
            )
        })
        .collect()
}

/// The generated graph's answers, by hand, as in the SimpleUML driver. `None`
/// for the tie schedule, held to "one of R7 and R9".
fn hand_computed(name: &str) -> Option<Projection> {
    Some(match name {
        "many-valued links on both replicas, then every target renamed" => expected(&[
            (A, "supertypes", &[B, C]),
            (B, "supertypes", &[C]),
            (AT, "typ", &[N]),
            (R7, "typ", &[B]),
            (R7, "opposite", &[R8]),
        ]),
        "concurrent adds to one many-valued reference" => expected(&[(A, "supertypes", &[B, D])]),
        "an unlink concurrent with an unlink and relink of the same target" => {
            expected(&[(A, "supertypes", &[B])])
        }
        "a deletion concurrent with a link to the deleted class" => expected(&[]),
        "Q2 on a many-valued reference" => expected(&[(A, "supertypes", &[D])]),
        "Q1 on a many-valued reference" => expected(&[(A, "supertypes", &[B])]),
        "a [1, 1] target deleted" => expected(&[(R7, "typ", &[N])]),
        "concurrent retarget of a [0, 1] reference" => return None,
        "concurrent retarget of a [0, 1] reference, then R9's class deleted" => {
            expected(&[(R7, "opposite", &[R7])])
        }
        "a class its own supertype, then deleted" => expected(&[]),
        "a full typ refuses a second link and its unlink" => expected(&[(AT, "typ", &[B])]),
        other => panic!("no hand-computed answer for `{other}`"),
    })
}

const CREATABLE: [(&str, &str, &str); 4] = [
    ("Package", "content", "Class"),
    ("Package", "content", "DataType"),
    ("Class", "features", "Attribute"),
    ("Class", "features", "Reference"),
];

/// R3 on every hand-written schedule, in both delivery orders.
#[test]
fn si05_r3_class_hierarchy_every_reference_schedule_reads_as_the_generated_graph() {
    let mut failures = Vec::new();
    let (mut runs, mut edits, mut refused, mut comparisons) = (0, 0, 0, 0);
    for (name, steps) in schedules() {
        for order in [Order::AFirst, Order::BFirst] {
            let mut twin = Twin::<Hierarchy>::new(&today(), &identity(), order);
            let mut all = opening();
            all.extend(steps.clone());
            runs += 1;
            if let Err(why) = twin.run(&all) {
                failures.push(format!("{name} ({order:?}): {why}"));
            }
            edits += twin.edits;
            refused += twin.refused;
            comparisons += twin.comparisons;
        }
    }
    println!(
        "SI05-R3 class_hierarchy hand schedules: {} schedules x 2 orders = {runs} runs, {edits} edits, \
         {refused} refused by the generated intake, {comparisons} comparisons",
        schedules().len()
    );
    assert!(
        failures.is_empty(),
        "{} of {runs} runs differ:\n\n{}",
        failures.len(),
        failures.join("\n\n")
    );
}

/// R3 and R4 on thirty seeded scripts.
#[test]
fn si05_r4_class_hierarchy_thirty_seeded_scripts_compare_every_reference() {
    let mut failures = Vec::new();
    let (mut edits, mut refused, mut comparisons, mut links) = (0, 0, 0, 0);
    for seed in 0..30u64 {
        match seeded::<Hierarchy>(
            &today(),
            &identity(),
            seed,
            seed >= 10,
            &opening(),
            &CREATABLE,
            false,
        ) {
            Ok(twin) => {
                edits += twin.edits;
                refused += twin.refused;
                comparisons += twin.comparisons;
                links += twin.links_read;
            }
            Err(why) => failures.push(why),
        }
    }
    println!(
        "SI05-R4 class_hierarchy seeded: 30 scripts, {edits} edits, {refused} refused by the generated intake, \
         {comparisons} comparisons, {links} links read at the peaks"
    );
    assert!(
        failures.is_empty(),
        "{} of 30 scripts differ:\n\n{}",
        failures.len(),
        failures.join("\n\n")
    );
    assert!(edits > 30 * 15, "thirty scripts came to only {edits} edits");
}

/// R4: every reference of this metamodel is in scope, each is driven, none is
/// left out.
#[test]
fn si05_r4_class_hierarchy_every_reference_is_in_scope_and_driven() {
    let descriptor = identity();
    let mut in_scope = BTreeSet::new();
    for (class, body) in descriptor["classes"].as_object().expect("classes") {
        for entry in body["references"]
            .as_array()
            .map(Vec::as_slice)
            .unwrap_or(&[])
        {
            assert_eq!(
                entry["merge"]["kind"],
                json!("identityReference"),
                "{class}.{} is left out",
                entry["name"]
            );
            in_scope.insert(format!(
                "{class}.{}",
                entry["name"].as_str().expect("a name")
            ));
        }
    }
    let expect: BTreeSet<String> = [
        "Class.supertypes",
        "Reference.opposite",
        "StructuralFeature.typ",
    ]
    .iter()
    .map(|n| n.to_string())
    .collect();
    assert_eq!(in_scope, expect);
}

/// The validator's own control on the harness, as for SimpleUML: every hand
/// schedule against the generated runtime alone ends at the hand-computed
/// answer, and the seeded scripts run. Green before SI.05.
#[test]
fn si05_harness_rehearsal_class_hierarchy_the_generated_half_reads_the_hand_computed_answers() {
    let mut wrong = Vec::new();
    for (name, steps) in schedules() {
        for order in [Order::AFirst, Order::BFirst] {
            let mut twin = Twin::<Hierarchy>::rehearsal(&today(), &identity(), order);
            let mut all = opening();
            all.extend(steps.clone());
            if let Err(why) = twin.run(&all) {
                wrong.push(format!(
                    "{name} ({order:?}): the rehearsal did not run: {why}"
                ));
                continue;
            }
            let got = twin.gen_projection('a').expect("a projection");
            match hand_computed(name) {
                Some(want) if got != want => wrong.push(format!(
                    "{name} ({order:?}): generated {got:?}, by hand {want:?}"
                )),
                Some(_) => {}
                None => {
                    let opposite = got
                        .get(&(R7, "opposite".to_string()))
                        .cloned()
                        .unwrap_or_default();
                    if opposite.len() != 1 || !(opposite.contains(&R7) || opposite.contains(&R9)) {
                        wrong.push(format!("{name} ({order:?}): R7.opposite reads {opposite:?}, not one of R7 and R9"));
                    }
                }
            }
            println!("SI05-REHEARSAL {name} ({order:?}): {got:?}");
        }
    }
    let (mut edits, mut links) = (0, 0);
    for seed in 0..30u64 {
        match seeded::<Hierarchy>(
            &today(),
            &identity(),
            seed,
            seed >= 10,
            &opening(),
            &CREATABLE,
            true,
        ) {
            Ok(twin) => {
                edits += twin.edits;
                links += twin
                    .gen_projection('a')
                    .expect("a projection")
                    .values()
                    .map(BTreeSet::len)
                    .sum::<usize>();
            }
            Err(why) => wrong.push(format!("seeded rehearsal: {why}")),
        }
    }
    println!(
        "SI05-REHEARSAL class_hierarchy seeded: 30 scripts, {edits} edits, {links} links read at the end"
    );
    assert!(
        wrong.is_empty(),
        "the harness or a hand answer is wrong:\n  {}",
        wrong.join("\n  ")
    );
    assert!(links > 30, "the seeded scripts end with only {links} links");
}
